/*
 * prog17_whitespace_trim.c
 *
 * Re‑implementation of the original program's observable behaviour.
 *
 * The original binary reads the first command‑line argument, trims leading
 * and trailing whitespace, collapses any internal runs of whitespace to a
 * single space character, and prints the resulting string.  If no argument
 * is supplied, or the resulting string is empty, the program prints the
 * literal word "EMPTY".
 *
 * Whitespace characters recognised by the original code are:
 *   space, '\t', '\n', '\r', '\v', '\f'
 *
 * The original implementation also limited the processed input to 1024
 * characters; longer inputs are silently truncated.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static bool is_ws(char c)
{
    return c == ' '  || c == '\t' || c == '\n' ||
           c == '\r' || c == '\v' || c == '\f';
}

int main(int argc, char *argv[])
{
    /* If no argument is supplied, the original program prints "EMPTY". */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *in = argv[1];
    /* The original binary truncates the input to 0x400 (1024) bytes. */
    size_t in_len = strnlen(in, 0x400);

    char out[0x401];          /* enough for the truncated input + NUL */
    size_t out_len = 0;

    size_t i = 0;

    /* Skip leading whitespace */
    while (i < in_len && is_ws(in[i]))
        ++i;

    for ( ; i < in_len; ++i) {
        if (is_ws(in[i])) {
            /* Skip the rest of this whitespace run */
            while (i + 1 < in_len && is_ws(in[i + 1]))
                ++i;

            /* If we are not at the end, emit a single space */
            if (i + 1 < in_len) {
                out[out_len++] = ' ';
            }
        } else {
            out[out_len++] = in[i];
        }
    }

    out[out_len] = '\0';

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
